#!/usr/bin/env bash
# Colour-bar clips for checking a device's picture against a known image (#416): the same SMPTE HD
# bars in each format the players decode, generated by FFmpeg (nothing filmed, nothing licensed).
#
#   scripts/colour-bars.sh <out dir>
#
# Needs: ffmpeg with libx264, libx265 and libsvtav1.
#
# Writes into <out dir>:
#   bars.png                    the bars as they should look (sRGB)
#   bars-h264-8bit.mp4          H.264 High, 8-bit 4:2:0, BT.709 limited range
#   bars-hevc-10bit.mp4         HEVC Main 10, 10-bit 4:2:0, BT.709 limited range
#   bars-hevc-10bit-pq.mp4      HEVC Main 10 tagged BT.2020 / PQ (HDR): shown tone-mapped, so
#                               dimmer and less saturated than bars.png, but never tinted
#   bars-av1-8bit.mp4           AV1, 8-bit 4:2:0, BT.709 limited range
#
# Each clip is 10 s at 24 fps, 1920x1080. On a correct picture the grey and white bars are neutral
# (no green, pink or blue cast), the bottom-left black patch is black, and the seven top bars run
# white-ish grey, yellow, cyan, green, magenta, red, blue.
set -euo pipefail

out=${1:?usage: scripts/colour-bars.sh <out dir>}
mkdir -p "$out"
src="smptehdbars=size=1920x1080:rate=24:duration=10"
bt709=(-color_primaries bt709 -color_trc bt709 -colorspace bt709 -color_range tv)
run() { ffmpeg -hide_banner -loglevel error -y -f lavfi -i "$src" "$@"; }

run -frames:v 1 -update 1 "$out/bars.png"
run -vf "scale=out_color_matrix=bt709:out_range=tv,format=yuv420p" -c:v libx264 -profile:v high -crf 16 \
	"${bt709[@]}" -movflags +faststart "$out/bars-h264-8bit.mp4"
run -vf "scale=out_color_matrix=bt709:out_range=tv,format=yuv420p10le" -c:v libx265 -profile:v main10 -crf 16 \
	-x265-params log-level=error "${bt709[@]}" -tag:v hvc1 -movflags +faststart "$out/bars-hevc-10bit.mp4"
run -vf "scale=out_color_matrix=bt2020:out_range=tv,format=yuv420p10le" -c:v libx265 -profile:v main10 -crf 16 \
	-x265-params "log-level=error:hdr10=1:colorprim=bt2020:transfer=smpte2084:colormatrix=bt2020nc:range=limited" \
	-color_primaries bt2020 -color_trc smpte2084 -colorspace bt2020nc -color_range tv -tag:v hvc1 -movflags +faststart \
	"$out/bars-hevc-10bit-pq.mp4"
run -vf "scale=out_color_matrix=bt709:out_range=tv,format=yuv420p" -c:v libsvtav1 -crf 20 -preset 8 \
	"${bt709[@]}" -movflags +faststart "$out/bars-av1-8bit.mp4"
ls -l "$out"
